{
  "message": "Migrated UserView to Pydantic v2; dependency pins remain unchanged.",
  "rationale": "ConfigDict enables attribute validation, field-name and alias population, and rejection of extra mapping fields. model_validate and model_dump use supported v2 APIs while preserving required-field validation, integer coercion, and output keys id and displayName.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "from pydantic import BaseModel, ConfigDict, Field


class UserView(BaseModel):
    model_config = ConfigDict(
        from_attributes=True,
        populate_by_name=True,
        extra="forbid",
    )

    id: int
    display_name: str = Field(alias="displayName")


def serialize_user(value):
    return UserView.model_validate(value).model_dump(by_alias=True)
